//! Configuration for tools you already use (#119): `limen config ssh --install`
//! and `limen kube config`.
//!
//! Both write generated files under `$LIMEN_HOME` and nothing long-lived: the
//! SSH entries run `limen ssh-proxy` and the kubeconfig runs
//! `limen kube credentials`, so every connection still needs a current login.
//!
//! Each proxy has its own fragment in its profile directory (`ssh_config`,
//! `kubeconfig.json`), written from `limen ls` when you install and again on
//! every `limen login`. The files tools read, `$LIMEN_HOME/ssh_config` and
//! `$LIMEN_HOME/kubeconfig`, join the fragments of every proxy, the current
//! one first, so logging in to a second proxy doesn't drop the first.
//!
//! The only file outside `$LIMEN_HOME` that is changed is `~/.ssh/config`,
//! which gets a marked block with one `Include` line at the top.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use anyhow::{Context as _, bail};
use limen_proto::v1::Resource;
use serde_json::json;

use crate::profile;
use crate::{api, ui};

/// Generated OpenSSH config that `~/.ssh/config` includes.
const SSH_CONFIG: &str = "ssh_config";
/// Generated kubeconfig, for `KUBECONFIG`.
const KUBECONFIG: &str = "kubeconfig";
/// Per-proxy fragments, in the profile directory.
const SSH_FRAGMENT: &str = "ssh_config";
const KUBE_FRAGMENT: &str = "kubeconfig.json";

const BLOCK_BEGIN: &str = "# >>> limen >>>";
const BLOCK_END: &str = "# <<< limen <<<";

/// A name that is safe to write into `ssh_config` or a kubeconfig as is: no
/// spaces, quotes, wildcards, or anything else OpenSSH would read as syntax.
/// Names come from policy, so this is a guard against a policy author, not
/// the user; anything else is skipped with a warning.
fn safe_name(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 253
        && !s.starts_with('-')
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"._-".contains(&b))
}

// ---- OpenSSH --------------------------------------------------------------------------

/// The `ssh_config` entries for one proxy's SSH resources, and the names
/// that were skipped because they aren't safe to write.
fn ssh_fragment(
    exe: &Path,
    proxy: &str,
    known_hosts: &Path,
    resources: &[Resource],
) -> (String, Vec<String>) {
    let mut out = format!("# SSH resources reached through {proxy}, from `limen ls`.\n");
    let mut skipped = Vec::new();
    for r in resources.iter().filter(|r| r.kind == "ssh") {
        if !safe_name(&r.name) {
            skipped.push(r.name.clone());
            continue;
        }
        let _ = writeln!(out, "Host {0} {0}.limen", r.name);
        // With exactly one login, plain `ssh <resource>` uses it.
        if let [login] = r.principals.as_slice()
            && safe_name(login)
        {
            let _ = writeln!(out, "    User {login}");
        }
        out.push_str(&ssh_option_lines(exe, proxy, known_hosts));
    }
    (out, skipped)
}

/// `ssh_options` as indented `ssh_config` lines. A `ProxyCommand` is the
/// rest of its line, already shell-quoted; other values with a space (a
/// home directory like `/Users/A B`) are quoted for OpenSSH.
pub(crate) fn ssh_option_lines(exe: &Path, proxy: &str, known_hosts: &Path) -> String {
    super::ssh::ssh_options(exe, proxy, known_hosts)
        .iter()
        .map(|o| {
            let (k, v) = o.split_once('=').unwrap_or((o.as_str(), ""));
            if k != "ProxyCommand" && v.contains(' ') {
                format!("    {k} \"{v}\"\n")
            } else {
                format!("    {k} {v}\n")
            }
        })
        .collect()
}

/// `$LIMEN_HOME/ssh_config`: every proxy's fragment, the current proxy's
/// first (OpenSSH uses the first value it finds), then `Host *.limen` for the
/// current proxy, which reaches resources added since the last refresh.
fn ssh_aggregate(fragments: &[String], fallback: &str) -> String {
    let mut out = String::from(
        "# Generated by limen. Don't edit: `limen login` and `limen config ssh --install` rewrite it.\n\n",
    );
    for fragment in fragments {
        out.push_str(fragment);
        out.push('\n');
    }
    out.push_str("# Any other <resource>.limen, through the current proxy.\nHost *.limen\n");
    out.push_str(fallback);
    out
}

/// `text` with the managed block, holding `include`, at the very top.
/// `Include` must come before any `Host` line to apply everywhere, and coming
/// first lets Limen's entries win for the names they define.
fn with_block(text: &str, include: &str) -> anyhow::Result<String> {
    let rest = without_block(text)?;
    Ok(format!(
        "{BLOCK_BEGIN} added by `limen config ssh --install`; `--uninstall` removes it\n{include}\n{BLOCK_END}\n\n{}",
        rest.trim_start_matches('\n')
    ))
}

/// `text` without the managed block. Refuses a half-removed block rather
/// than guess which lines are ours.
fn without_block(text: &str) -> anyhow::Result<String> {
    let Some(start) = text.find(BLOCK_BEGIN) else {
        return Ok(text.to_owned());
    };
    let Some(end) = text[start..].find(BLOCK_END).map(|i| start + i) else {
        bail!("found `{BLOCK_BEGIN}` without `{BLOCK_END}`; fix or remove the block by hand");
    };
    let after = text[end + BLOCK_END.len()..]
        .strip_prefix('\n')
        .unwrap_or(&text[end + BLOCK_END.len()..]);
    let after = if start == 0 {
        after.trim_start_matches('\n')
    } else {
        after
    };
    Ok(format!("{}{after}", &text[..start]))
}

/// The `Include` line for `path`, quoted if it has spaces.
fn include_line(path: &Path) -> String {
    let p = path.display().to_string();
    if p.contains(' ') {
        format!("Include \"{p}\"")
    } else {
        format!("Include {p}")
    }
}

/// `~/.ssh/config`.
fn default_ssh_config() -> anyhow::Result<PathBuf> {
    let home = std::env::var_os("HOME").context("HOME is not set; use --file")?;
    Ok(PathBuf::from(home).join(".ssh").join("config"))
}

/// `limen config ssh --install`.
pub async fn install_ssh(proxy: Option<&str>, file: Option<&Path>) -> anyhow::Result<()> {
    let proxy = api::resolve_proxy(proxy)?;
    let resources = fetch(&proxy).await?;
    let count = write_ssh_fragment(&proxy, &resources)?;
    let generated = rebuild_ssh(&proxy)?;
    let config = match file {
        Some(f) => f.to_owned(),
        None => default_ssh_config()?,
    };
    edit_config_file(&config, |text| with_block(text, &include_line(&generated)))?;
    ui::success(&format!(
        "{} now includes {} ({count} SSH resource{}).",
        config.display(),
        generated.display(),
        if count == 1 { "" } else { "s" }
    ));
    if let Some(r) = resources
        .iter()
        .find(|r| r.kind == "ssh" && safe_name(&r.name))
    {
        ui::hint(&format!(
            "Try `ssh {}`. scp, rsync and git use the same names.",
            r.name
        ));
    }
    ui::hint("The list is refreshed on every `limen login`.");
    Ok(())
}

/// `limen config ssh --uninstall`.
pub fn uninstall_ssh(file: Option<&Path>) -> anyhow::Result<()> {
    let config = match file {
        Some(f) => f.to_owned(),
        None => default_ssh_config()?,
    };
    if config.exists() {
        edit_config_file(&config, without_block)?;
    }
    remove_generated(SSH_CONFIG, SSH_FRAGMENT)?;
    ui::success(&format!(
        "Removed Limen's entries from {}.",
        config.display()
    ));
    Ok(())
}

/// Write this proxy's SSH fragment. Returns how many resources it names.
fn write_ssh_fragment(proxy: &str, resources: &[Resource]) -> anyhow::Result<usize> {
    let exe = std::env::current_exe().context("locating the limen executable")?;
    let known_hosts = profile::dir_for(proxy)?.join(super::ssh::KNOWN_HOSTS);
    let (text, skipped) = ssh_fragment(&exe, proxy, &known_hosts, resources);
    for name in &skipped {
        ui::warn(&format!(
            "Skipped {name:?}: not a name OpenSSH can take as a host alias. Use `limen ssh {name}`."
        ));
    }
    profile::write_file(&profile::dir_for(proxy)?.join(SSH_FRAGMENT), &text, false)?;
    Ok(resources.iter().filter(|r| r.kind == "ssh").count() - skipped.len())
}

/// Rewrite `$LIMEN_HOME/ssh_config` from every proxy's fragment.
fn rebuild_ssh(current: &str) -> anyhow::Result<PathBuf> {
    let fragments = fragments(current, SSH_FRAGMENT)?
        .into_iter()
        .map(|(_, text)| text)
        .collect::<Vec<_>>();
    let exe = std::env::current_exe().context("locating the limen executable")?;
    let known_hosts = profile::dir_for(current)?.join(super::ssh::KNOWN_HOSTS);
    let fallback = ssh_option_lines(&exe, current, &known_hosts);
    let path = profile::home()?.join(SSH_CONFIG);
    profile::write_file(&path, &ssh_aggregate(&fragments, &fallback), false)?;
    Ok(path)
}

/// Edit a config file in place, following a symlink (dotfile managers link
/// `~/.ssh/config`) and keeping its permissions. A new file is mode 0600 in a
/// 0700 directory, as OpenSSH expects.
fn edit_config_file(
    path: &Path,
    edit: impl FnOnce(&str) -> anyhow::Result<String>,
) -> anyhow::Result<()> {
    let target = if path.exists() {
        std::fs::canonicalize(path).with_context(|| format!("resolving {}", path.display()))?
    } else {
        path.to_owned()
    };
    let current = match std::fs::read_to_string(&target) {
        Ok(text) => Some(text),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
        Err(e) => {
            return Err(anyhow::Error::new(e).context(format!("reading {}", target.display())));
        }
    };
    let updated = edit(current.as_deref().unwrap_or(""))
        .with_context(|| format!("updating {}", target.display()))?;
    if current.as_deref() == Some(updated.as_str()) {
        return Ok(());
    }
    let dir = target.parent().context("config file has no directory")?;
    if !dir.exists() {
        std::fs::create_dir_all(dir)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            std::fs::set_permissions(dir, std::fs::Permissions::from_mode(0o700))?;
        }
    }
    let tmp = target.with_extension("limen-tmp");
    std::fs::write(&tmp, &updated).with_context(|| format!("writing {}", tmp.display()))?;
    let permissions = match std::fs::metadata(&target) {
        Ok(m) => m.permissions(),
        Err(_) => {
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                std::fs::Permissions::from_mode(0o600)
            }
            #[cfg(not(unix))]
            std::fs::metadata(&tmp)?.permissions()
        }
    };
    std::fs::set_permissions(&tmp, permissions)?;
    std::fs::rename(&tmp, &target).with_context(|| format!("replacing {}", target.display()))?;
    Ok(())
}

/// Whether `~/.ssh/config` (or `file`) includes Limen's generated config.
pub fn ssh_installed(file: Option<&Path>) -> anyhow::Result<bool> {
    let config = match file {
        Some(f) => f.to_owned(),
        None => default_ssh_config()?,
    };
    Ok(std::fs::read_to_string(config).is_ok_and(|t| t.contains(BLOCK_BEGIN)))
}

// ---- kubectl --------------------------------------------------------------------------

/// The kubeconfig entries for one proxy's clusters, as a kubeconfig without
/// a current context, and the names that were skipped.
fn kube_fragment(
    exe: &Path,
    proxy: &str,
    ca_pem: Option<&str>,
    home: Option<&Path>,
    resources: &[Resource],
) -> (serde_json::Value, Vec<String>) {
    let user = format!("limen@{proxy}");
    let mut clusters = Vec::new();
    let mut contexts = Vec::new();
    let mut skipped = Vec::new();
    for r in resources.iter().filter(|r| r.kind == "kubernetes") {
        if !safe_name(&r.name) {
            skipped.push(r.name.clone());
            continue;
        }
        let name = format!("limen-{}", r.name);
        clusters.push(json!({
            "name": name,
            "cluster": super::kube::cluster_entry(proxy, &r.name, ca_pem),
        }));
        contexts.push(json!({ "name": name, "context": { "cluster": name, "user": user } }));
    }
    let users = if clusters.is_empty() {
        vec![]
    } else {
        vec![json!({ "name": user, "user": { "exec": super::kube::exec_entry(proxy, exe, home) } })]
    };
    (
        json!({
            "apiVersion": "v1",
            "kind": "Config",
            "clusters": clusters,
            "users": users,
            "contexts": contexts,
        }),
        skipped,
    )
}

/// Join kubeconfig fragments. A context name already taken by an earlier
/// (current-first) proxy is left out, and returned.
fn kube_aggregate(fragments: &[serde_json::Value]) -> (serde_json::Value, Vec<String>) {
    let mut seen = std::collections::HashSet::new();
    let (mut clusters, mut users, mut contexts, mut dropped) = (vec![], vec![], vec![], vec![]);
    for f in fragments {
        let list = |key: &str| f[key].as_array().cloned().unwrap_or_default();
        let mut kept_any = false;
        for (cluster, context) in list("clusters").into_iter().zip(list("contexts")) {
            let name = context["name"].as_str().unwrap_or_default().to_owned();
            if seen.insert(name.clone()) {
                clusters.push(cluster);
                contexts.push(context);
                kept_any = true;
            } else {
                dropped.push(name);
            }
        }
        if kept_any {
            users.extend(list("users"));
        }
    }
    (
        json!({
            "apiVersion": "v1",
            "kind": "Config",
            "preferences": {},
            "clusters": clusters,
            "users": users,
            "contexts": contexts,
        }),
        dropped,
    )
}

/// `limen kube config`.
pub async fn install_kube(proxy: Option<&str>, print: bool) -> anyhow::Result<()> {
    let proxy = api::resolve_proxy(proxy)?;
    let resources = fetch(&proxy).await?;
    if print {
        let (fragment, _) = kube_fragment_for(&proxy, &resources)?;
        anstream::println!("{}", serde_json::to_string_pretty(&fragment)?);
        return Ok(());
    }
    let names = write_kube_fragment(&proxy, &resources)?;
    let path = rebuild_kube(&proxy)?;
    ui::success(&format!(
        "Wrote {} with {} cluster context{}.",
        path.display(),
        names.len(),
        if names.len() == 1 { "" } else { "s" }
    ));
    ui::hint(&format!(
        "Add it to kubectl's search path, for example in your shell profile:\n    export KUBECONFIG=\"${{KUBECONFIG:-$HOME/.kube/config}}:{}\"",
        path.display()
    ));
    if let Some(first) = names.first() {
        ui::hint(&format!("Then `kubectl --context {first} get pods`."));
    }
    ui::hint("The contexts are refreshed on every `limen login`.");
    Ok(())
}

/// `limen kube config --uninstall`.
pub fn uninstall_kube() -> anyhow::Result<()> {
    remove_generated(KUBECONFIG, KUBE_FRAGMENT)?;
    ui::success("Removed Limen's generated kubeconfig.");
    ui::hint("Remove it from KUBECONFIG in your shell profile too.");
    Ok(())
}

fn kube_fragment_for(
    proxy: &str,
    resources: &[Resource],
) -> anyhow::Result<(serde_json::Value, Vec<String>)> {
    let exe = std::env::current_exe().context("locating the limen executable")?;
    let ca = profile::trusted_ca(proxy)?;
    let home = std::env::var_os("LIMEN_HOME").map(PathBuf::from);
    Ok(kube_fragment(
        &exe,
        proxy,
        ca.as_deref(),
        home.as_deref(),
        resources,
    ))
}

/// Write this proxy's kubeconfig fragment. Returns its context names.
fn write_kube_fragment(proxy: &str, resources: &[Resource]) -> anyhow::Result<Vec<String>> {
    let (fragment, skipped) = kube_fragment_for(proxy, resources)?;
    for name in &skipped {
        ui::warn(&format!(
            "Skipped {name:?}: not a name that can be a kubeconfig context. Use `limen kube login {name}`."
        ));
    }
    profile::write_file(
        &profile::dir_for(proxy)?.join(KUBE_FRAGMENT),
        &serde_json::to_string_pretty(&fragment)?,
        true,
    )?;
    Ok(fragment["contexts"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|c| c["name"].as_str().map(str::to_owned))
        .collect())
}

/// Rewrite `$LIMEN_HOME/kubeconfig` from every proxy's fragment.
fn rebuild_kube(current: &str) -> anyhow::Result<PathBuf> {
    let fragments = fragments(current, KUBE_FRAGMENT)?
        .into_iter()
        .filter_map(|(dir, text)| match serde_json::from_str(&text) {
            Ok(v) => Some(v),
            Err(e) => {
                ui::warn(&format!(
                    "Ignoring {}: {e}",
                    dir.join(KUBE_FRAGMENT).display()
                ));
                None
            }
        })
        .collect::<Vec<_>>();
    let (config, dropped) = kube_aggregate(&fragments);
    for name in dropped {
        ui::warn(&format!(
            "Context {name} exists through two proxies; kept the current proxy's."
        ));
    }
    let path = profile::home()?.join(KUBECONFIG);
    // kubectl warns about kubeconfigs others can read.
    profile::write_file(&path, &serde_json::to_string_pretty(&config)?, true)?;
    Ok(path)
}

// ---- shared ---------------------------------------------------------------------------

/// Every profile's fragment `name`, the current proxy's first, the rest by
/// directory name so the output is stable.
fn fragments(current: &str, name: &str) -> anyhow::Result<Vec<(PathBuf, String)>> {
    let current_dir = profile::dir_for(current)?;
    let mut dirs = match std::fs::read_dir(profile::home()?.join("profiles")) {
        Ok(entries) => entries
            .filter_map(Result::ok)
            .map(|e| e.path())
            .filter(|p| *p != current_dir)
            .collect::<Vec<_>>(),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => vec![],
        Err(e) => return Err(e.into()),
    };
    dirs.sort();
    dirs.insert(0, current_dir);
    Ok(dirs
        .into_iter()
        .filter_map(|dir| {
            let text = std::fs::read_to_string(dir.join(name)).ok()?;
            Some((dir, text))
        })
        .collect())
}

/// Remove a generated file and every profile's fragment of it.
fn remove_generated(generated: &str, fragment: &str) -> anyhow::Result<()> {
    let home = profile::home()?;
    remove_if_present(&home.join(generated))?;
    if let Ok(entries) = std::fs::read_dir(home.join("profiles")) {
        for entry in entries.filter_map(Result::ok) {
            remove_if_present(&entry.path().join(fragment))?;
        }
    }
    Ok(())
}

fn remove_if_present(path: &Path) -> anyhow::Result<()> {
    match std::fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(e) => Err(anyhow::Error::new(e).context(format!("removing {}", path.display()))),
    }
}

async fn fetch(proxy: &str) -> anyhow::Result<Vec<Resource>> {
    super::fetch_resources(Some(proxy)).await
}

/// After a login: regenerate whichever integrations are installed, so they
/// list what this login may reach. Problems are warnings; the login stands.
pub async fn refresh_after_login(proxy: &str) {
    let Ok(home) = profile::home() else { return };
    let ssh = home.join(SSH_CONFIG).exists();
    let kube = home.join(KUBECONFIG).exists();
    if !ssh && !kube {
        return;
    }
    let result = async {
        let resources = fetch(proxy).await?;
        if ssh {
            write_ssh_fragment(proxy, &resources)?;
            rebuild_ssh(proxy)?;
        }
        if kube {
            write_kube_fragment(proxy, &resources)?;
            rebuild_kube(proxy)?;
        }
        anyhow::Ok(())
    }
    .await;
    if let Err(e) = result {
        ui::warn(&format!(
            "Couldn't refresh the generated ssh_config/kubeconfig ({e:#}). Run `limen config ssh --install` or `limen kube config` to retry."
        ));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn resource(name: &str, kind: &str, principals: &[&str]) -> Resource {
        Resource {
            name: name.into(),
            kind: kind.into(),
            principals: principals.iter().map(|p| (*p).into()).collect(),
            ..Default::default()
        }
    }

    #[test]
    fn unsafe_names_are_refused() {
        for ok in ["web-1", "orders.prod", "a_b", "A9"] {
            assert!(safe_name(ok), "{ok}");
        }
        for bad in [
            "",
            "-oProxyCommand",
            "a b",
            "x\nProxyCommand evil",
            "*",
            "web?",
            "!web",
            "\"q\"",
            "a/b",
            &"a".repeat(254),
        ] {
            assert!(!safe_name(bad), "{bad:?}");
        }
    }

    #[test]
    fn ssh_fragment_has_one_block_per_ssh_resource() {
        let (text, skipped) = ssh_fragment(
            Path::new("/usr/bin/limen"),
            "limen.example:443",
            Path::new("/h/known_hosts"),
            &[
                resource("web-1", "ssh", &["ubuntu"]),
                resource("bastion", "ssh", &["ec2-user", "ubuntu"]),
                resource("orders", "postgres", &["read"]),
                resource("evil\nHost *", "ssh", &["root"]),
            ],
        );
        assert_eq!(skipped, ["evil\nHost *"]);
        assert!(text.contains("Host web-1 web-1.limen\n    User ubuntu\n    ProxyCommand /usr/bin/limen --proxy limen.example:443 ssh-proxy %r %h\n"));
        // Two logins: the user names one, so no User line.
        assert!(text.contains("Host bastion bastion.limen\n    ProxyCommand"));
        assert!(!text.contains("orders") && !text.contains("evil"));
        assert!(text.contains("    IdentityAgent none\n"));
        assert!(text.contains("    UserKnownHostsFile /h/known_hosts\n"));
    }

    #[test]
    fn aggregate_keeps_fragment_order_and_ends_with_the_fallback() {
        let text = ssh_aggregate(
            &["# a\nHost x\n".into(), "# b\nHost y\n".into()],
            "    ProxyCommand p\n",
        );
        let a = text.find("# a").expect("a");
        let b = text.find("# b").expect("b");
        let star = text
            .find("Host *.limen\n    ProxyCommand p")
            .expect("fallback");
        assert!(a < b && b < star);
    }

    #[test]
    fn block_goes_on_top_and_comes_out_cleanly() {
        let original = "Host github.com\n    User git\n";
        let with = with_block(original, "Include /h/.limen/ssh_config").expect("add");
        assert!(with.starts_with(BLOCK_BEGIN));
        assert!(with.ends_with(original));
        assert_eq!(with.matches(BLOCK_BEGIN).count(), 1);
        // Installing again replaces the block instead of adding a second one.
        let again = with_block(&with, "Include /other/ssh_config").expect("again");
        assert_eq!(again.matches(BLOCK_BEGIN).count(), 1);
        assert!(again.contains("/other/") && !again.contains("/h/.limen"));
        assert_eq!(without_block(&again).expect("remove"), original);
        // Into an empty or missing file.
        let fresh = with_block("", "Include x").expect("fresh");
        assert_eq!(without_block(&fresh).expect("remove"), "");
        // A block someone moved further down is still removed, and nothing else.
        let moved = format!("Host a\n{BLOCK_BEGIN}\nInclude x\n{BLOCK_END}\nHost b\n");
        assert_eq!(without_block(&moved).expect("remove"), "Host a\nHost b\n");
        assert!(without_block(&format!("{BLOCK_BEGIN}\nInclude x\n")).is_err());
    }

    #[test]
    fn include_paths_with_spaces_are_quoted() {
        assert_eq!(
            include_line(Path::new("/h/.limen/ssh_config")),
            "Include /h/.limen/ssh_config"
        );
        assert_eq!(
            include_line(Path::new("/Users/A B/.limen/ssh_config")),
            "Include \"/Users/A B/.limen/ssh_config\""
        );
    }

    #[cfg(unix)]
    #[test]
    fn editing_follows_symlinks_and_keeps_permissions() {
        use std::os::unix::fs::PermissionsExt as _;
        let dir = tempfile::tempdir().expect("tmp");
        let real = dir.path().join("dotfiles-ssh-config");
        std::fs::write(&real, "Host a\n").expect("write");
        std::fs::set_permissions(&real, std::fs::Permissions::from_mode(0o640)).expect("chmod");
        let link = dir.path().join("config");
        std::os::unix::fs::symlink(&real, &link).expect("link");
        edit_config_file(&link, |t| with_block(t, "Include x")).expect("edit");
        assert!(
            std::fs::symlink_metadata(&link)
                .expect("meta")
                .file_type()
                .is_symlink()
        );
        assert!(
            std::fs::read_to_string(&real)
                .expect("read")
                .contains("Include x")
        );
        assert_eq!(
            std::fs::metadata(&real).expect("meta").permissions().mode() & 0o777,
            0o640
        );
        // A new file is private, in a private directory.
        let fresh = dir.path().join("new").join("config");
        edit_config_file(&fresh, |t| with_block(t, "Include x")).expect("create");
        assert_eq!(
            std::fs::metadata(&fresh)
                .expect("meta")
                .permissions()
                .mode()
                & 0o777,
            0o600
        );
        assert_eq!(
            std::fs::metadata(fresh.parent().expect("dir"))
                .expect("meta")
                .permissions()
                .mode()
                & 0o777,
            0o700
        );
    }

    #[test]
    fn kube_fragment_names_contexts_and_holds_no_credential() {
        let (cfg, skipped) = kube_fragment(
            Path::new("/bin/limen"),
            "limen.example:8443",
            Some("CA"),
            None,
            &[
                resource("eks-dev", "kubernetes", &["dev"]),
                resource("web-1", "ssh", &["ubuntu"]),
                resource("bad name", "kubernetes", &["dev"]),
            ],
        );
        assert_eq!(skipped, ["bad name"]);
        assert_eq!(cfg["contexts"][0]["name"], "limen-eks-dev");
        assert_eq!(
            cfg["contexts"][0]["context"]["user"],
            "limen@limen.example:8443"
        );
        assert_eq!(
            cfg["clusters"][0]["cluster"]["server"],
            "https://limen.example:8443/k8s/eks-dev"
        );
        assert_eq!(cfg["users"][0]["user"]["exec"]["args"][3], "credentials");
        assert!(
            cfg.get("current-context").is_none(),
            "don't take over kubectl's context"
        );
        let text = cfg.to_string();
        assert!(!text.contains("client-key") && !text.contains("token"));
        // No clusters, no user entry either.
        let (empty, _) = kube_fragment(Path::new("/bin/limen"), "p:1", None, None, &[]);
        assert_eq!(empty["users"], json!([]));
    }

    #[test]
    fn kube_aggregate_prefers_the_first_proxy_on_a_name_clash() {
        let frag = |proxy: &str, clusters: &[&str]| {
            kube_fragment(
                Path::new("/bin/limen"),
                proxy,
                None,
                None,
                &clusters
                    .iter()
                    .map(|c| resource(c, "kubernetes", &["dev"]))
                    .collect::<Vec<_>>(),
            )
            .0
        };
        let (cfg, dropped) = kube_aggregate(&[
            frag("current:443", &["eks-a"]),
            frag("other:443", &["eks-a", "eks-b"]),
            frag("only-clash:443", &["eks-a"]),
        ]);
        assert_eq!(dropped, ["limen-eks-a", "limen-eks-a"]);
        let contexts: Vec<_> = cfg["contexts"]
            .as_array()
            .expect("contexts")
            .iter()
            .map(|c| {
                (
                    c["name"].as_str().expect("name"),
                    c["context"]["user"].as_str().expect("user"),
                )
            })
            .collect();
        assert_eq!(
            contexts,
            [
                ("limen-eks-a", "limen@current:443"),
                ("limen-eks-b", "limen@other:443")
            ]
        );
        // A proxy whose every context was dropped adds no dangling user.
        let users: Vec<_> = cfg["users"]
            .as_array()
            .expect("users")
            .iter()
            .map(|u| u["name"].as_str().expect("name"))
            .collect();
        assert_eq!(users, ["limen@current:443", "limen@other:443"]);
    }
}
